/// Parses the instruction whose opcode byte is b in the given map.
let parse (span: ByteSpan) (st: byref<DState>) (map: int) (b: int) =
  match map with
  | 0 -> map0 span &st b
  | 1 -> map1 span &st b
  | 2 -> map2 span &st b
  | _ -> map3 span &st b
